import { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useStore } from '@/store';
import Card from '@/components/ui/Card';
import Button from '@/components/ui/Button';
import Input from '@/components/ui/Input';
import Dialog from '@/components/ui/Dialog';
import { Database, Download, Upload, HelpCircle, Banknote, Lock } from 'lucide-react';

export default function Settings() {
  const navigate = useNavigate();
    const s = useStore();
      const [currency, setCurrency] = useState(s.settings?.currency || 'ريال يمني');
        const [passcodeOpen, setPasscodeOpen] = useState(false);
          const [newPasscode, setNewPasscode] = useState('');
            const [confirmPasscode, setConfirmPasscode] = useState('');
              const [isLocked, setIsLocked] = useState(!!localStorage.getItem('app-passcode'));
                const fileInputRef = useRef<HTMLInputElement>(null);

                  // نسخ احتياطي تلقائي يومي
                    useEffect(() => {
                        const lastBackup = localStorage.getItem('last-auto-backup');
                            const today = new Date().toISOString().split('T')[0];
                                if (lastBackup !== today) {
                                      autoBackup();
                                          }
                                            }, []);

                                              const autoBackup = () => {
                                                  try {
                                                        const data = JSON.stringify(s, null, 2);
                                                              const fileName = `bakala-auto-${new Date().toISOString().split('T')[0]}.json`;
                                                                    const backups = JSON.parse(localStorage.getItem('bakala-backups') || '[]');
                                                                          backups.unshift({ name: fileName, date: new Date().toISOString().split('T')[0], data });
                                                                                if (backups.length > 30) backups.pop();
                                                                                      localStorage.setItem('bakala-backups', JSON.stringify(backups));
                                                                                            localStorage.setItem('last-auto-backup', new Date().toISOString().split('T')[0]);
                                                                                                } catch {}
                                                                                                  };

                                                                                                    const saveCurrency = () => {
                                                                                                        s.settings = { ...s.settings, currency };
                                                                                                            localStorage.setItem('grocery-settings', JSON.stringify(s.settings));
                                                                                                              };

                                                                                                                const exportBackup = () => {
                                                                                                                    const data = JSON.stringify(s, null, 2);
                                                                                                                        const blob = new Blob([data], { type: 'application/json' });
                                                                                                                            const fileName = `bakala-backup-${new Date().toISOString().split('T')[0]}.json`;
                                                                                                                                const url = URL.createObjectURL(blob);
                                                                                                                                    const a = document.createElement('a');
                                                                                                                                        a.href = url;
                                                                                                                                            a.download = fileName;
                                                                                                                                                a.click();
                                                                                                                                                    URL.revokeObjectURL(url);

                                                                                                                                                        const file = new File([blob], fileName, { type: 'application/json' });
                                                                                                                                                            if (navigator.share && navigator.canShare({ files: [file] })) {
                                                                                                                                                                  navigator.share({ title: 'نسخة احتياطية', files: [file] });
                                                                                                                                                                      }
                                                                                                                                                                        };

                                                                                                                                                                          const importBackup = (e: React.ChangeEvent<HTMLInputElement>) => {
                                                                                                                                                                              const file = e.target.files?.[0];
                                                                                                                                                                                  if (!file) return;

                                                                                                                                                                                      const reader = new FileReader();
                                                                                                                                                                                          reader.onload = (event) => {
                                                                                                                                                                                                try {
                                                                                                                                                                                                        const data = JSON.parse(event.target?.result as string);
                                                                                                                                                                                                                if (confirm('سيتم استبدال جميع البيانات الحالية. هل أنت متأكد؟')) {
                                                                                                                                                                                                                          localStorage.setItem('grocery-store', JSON.stringify(data));
                                                                                                                                                                                                                                    window.location.reload();
                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                  } catch {
                                                                                                                                                                                                                                                          alert('ملف غير صالح');
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                    };
                                                                                                                                                                                                                                                                        reader.readAsText(file);
                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                            const savePasscode = () => {
                                                                                                                                                                                                                                                                                if (!newPasscode) { alert('أدخل رمز المرور'); return; }
                                                                                                                                                                                                                                                                                    if (newPasscode !== confirmPasscode) { alert('الرمز غير متطابق'); return; }
                                                                                                                                                                                                                                                                                        localStorage.setItem('app-passcode', newPasscode);
                                                                                                                                                                                                                                                                                            setIsLocked(true);
                                                                                                                                                                                                                                                                                                setPasscodeOpen(false);
                                                                                                                                                                                                                                                                                                    setNewPasscode('');
                                                                                                                                                                                                                                                                                                        setConfirmPasscode('');
                                                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                                                            const removePasscode = () => {
                                                                                                                                                                                                                                                                                                                localStorage.removeItem('app-passcode');
                                                                                                                                                                                                                                                                                                                    setIsLocked(false);
                                                                                                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                                                                                            <div className="page-container">
                                                                                                                                                                                                                                                                                                                                  <h1 className="page-title">الإعدادات</h1>

                                                                                                                                                                                                                                                                                                                                        <div className="space-y-4">
                                                                                                                                                                                                                                                                                                                                                <div>
                                                                                                                                                                                                                                                                                                                                                          <h3 className="text-card-title text-text-primary mb-2">تعليمات</h3>
                                                                                                                                                                                                                                                                                                                                                                    <div className="space-y-2">
                                                                                                                                                                                                                                                                                                                                                                                <Card className="flex items-center gap-3 cursor-pointer hover:shadow-card-hover transition-shadow" onClick={() => navigate('/guide')}>
                                                                                                                                                                                                                                                                                                                                                                                              <div className="bg-info/10 p-2 rounded-lg"><HelpCircle size={20} className="text-info" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                            <div><p className="font-semibold">طريقة استخدام التطبيق</p><p className="text-small text-text-secondary">شرح كامل لطريقة استخدام جميع أقسام التطبيق</p></div>
                                                                                                                                                                                                                                                                                                                                                                                                                        </Card>
                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                            <h3 className="text-card-title text-text-primary mb-2">الأمان</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="space-y-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Card className="flex items-center gap-3 cursor-pointer hover:shadow-card-hover transition-shadow" onClick={() => { setNewPasscode(''); setConfirmPasscode(''); setPasscodeOpen(true); }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="bg-primary-light p-2 rounded-lg"><Lock size={20} className="text-primary" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p className="font-semibold">{isLocked ? 'تغيير رمز المرور' : 'تفعيل قفل التطبيق'}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p className="text-small text-text-secondary">{isLocked ? 'التطبيق مقفل برمز مرور' : 'قفل التطبيق برمز مرور أو بصمة'}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </Card>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {isLocked && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Card className="flex items-center gap-3 cursor-pointer hover:shadow-card-hover transition-shadow !border-r-danger" onClick={removePasscode}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="bg-danger/10 p-2 rounded-lg"><Lock size={20} className="text-danger" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div><p className="font-semibold text-danger">إلغاء القفل</p><p className="text-small text-text-secondary">إزالة رمز المرور</p></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </Card>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <h3 className="text-card-title text-text-primary mb-2">العملة</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="space-y-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Card>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="flex items-center gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="bg-primary-light p-2 rounded-lg"><Banknote size={20} className="text-primary" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="flex-1"><Input value={currency} onChange={e => setCurrency(e.target.value)} /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Button onClick={saveCurrency}>حفظ</Button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </Card>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <h3 className="text-card-title text-text-primary mb-2">النسخ الاحتياطي</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="space-y-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Card className="flex items-center gap-3 cursor-pointer hover:shadow-card-hover transition-shadow" onClick={exportBackup}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="bg-primary-light p-2 rounded-lg"><Download size={20} className="text-primary" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div><p className="font-semibold">نسخ احتياطي</p><p className="text-small text-text-secondary">حفظ ومشاركة نسخة من جميع البيانات</p></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </Card>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Card className="flex items-center gap-3 cursor-pointer hover:shadow-card-hover transition-shadow" onClick={() => fileInputRef.current?.click()}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="bg-primary-light p-2 rounded-lg"><Upload size={20} className="text-primary" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div><p className="font-semibold">استعادة نسخة احتياطية</p><p className="text-small text-text-secondary">استعادة البيانات من ملف نسخة احتياطية</p></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </Card>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <input ref={fileInputRef} type="file" accept=".json" onChange={importBackup} className="hidden" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <h3 className="text-card-title text-text-primary mb-2">معلومات</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="space-y-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Card className="flex items-center gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="bg-primary-light p-2 rounded-lg"><Database size={20} className="text-primary" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div><p className="font-semibold">الإصدار</p><p className="text-small text-text-secondary">1.0.0</p></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </Card>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Card className="!bg-primary/5 !border-primary/20">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="text-center">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p className="font-bold text-primary text-body">Mohandes Digital</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p className="text-small text-text-secondary mt-1">Building Smart Digital Solutions</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <a
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              href="https://wa.me/967778880031"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                target="_blank"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  rel="noopener noreferrer"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    className="inline-flex items-center gap-2 mt-3 px-4 py-2 bg-success text-white rounded-btn text-small font-semibold hover:bg-success/90 transition-colors"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z"/></svg>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        واتساب
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </a>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </Card>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Dialog open={passcodeOpen} onClose={() => setPasscodeOpen(false)} title={isLocked ? 'تغيير رمز المرور' : 'تفعيل قفل التطبيق'}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="space-y-3 pb-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Input label="رمز المرور (4-6 أرقام)" type="number" value={newPasscode} onChange={e => setNewPasscode(e.target.value.slice(0, 6))} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Input label="تأكيد رمز المرور" type="number" value={confirmPasscode} onChange={e => setConfirmPasscode(e.target.value.slice(0, 6))} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Button fullWidth onClick={savePasscode}>{isLocked ? 'تغيير الرمز' : 'تفعيل القفل'}</Button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </Dialog>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }